WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_average_growth_amount'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '平均数增长量', 'kp-xingce-data-average-growth-amount', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "平均数增长量"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "求平均数的绝对变化数值。公式形式与“比重差”完全一致。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这道题要求的是绝对量，比如：“今年每台车的均价比去年贵了多少元？” 选项是具体的带单位的数值。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "平均数增量 = \\frac{A}{B} \\times \\frac{a - b}{1 + a}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "（注意：这里的公式形式和比重变化量一模一样，都是乘以 (a-b)/(1+a)）"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤（绝对上限边界法）"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出复杂增量公式] --> B[先算出差值率 |a - b|]\nB --> C[用现期平均数 A/B 直接去乘以 |a-b|, 得出一个粗略上限值]\nC --> D{观察选项}\nD -- 只有一个符合特征 --> E[最终结果必定小于粗略上限, 秒选]\nD -- 两个符合特征 --> F[除以 (1+a) 进行精确计算]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 旅游总收入 1500 亿元，增长 30%(a)；游客总数 500 万人，增长 20%(b)。求人均旅游消费比上年增加了多少元？选项：A. 1500 B. 2300 C. 3000 D. 3600"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算现期均值：A/B = 1500亿 / 500万 = 30000元/人。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算粗略上限：差值 a-b = 10%。粗略上限 = 30000 × 10% = 3000元。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "判断真实值：真实值需要除以 (1+a) 即 1.3，必定小于 3000元。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定选项：找小于 3000 且最靠谱的，选 B (2300)。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "强行精算到底：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多考生遇到这种题，真的去算 30000 × 10% ÷ 1.3，结果除个半天。资料分析考的是“分析”，掌握了边界值就能利用选项的差异进行降维打击。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到这种三连操作（两除一减）的题，强制自己停笔 3 秒钟，用估算法找个上限去套选项。"}]}]}$$ AS jsonb), NULL, '平均数增长量的核心考点与实战推导。', category_node.id, CAST('["资料分析", "平均数增长量"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_average_growth_amount", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
